function validate([distance]) {
  if (distance.length < 1 || distance.length > 100000) return 'distance needs 1 to 10^5 moves.';
  if (distance.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each move is a whole number from 1 to 10^5.';
  return null;
}

