function isSelfCrossing(distance) {
  const d = distance;
  for (let i = 3; i < d.length; i++) {
    // Move i hits move i - 3 (the segment it turns back towards).
    if (d[i] >= d[i - 2] && d[i - 1] <= d[i - 3]) {
      return true;
    }
    // Move i runs head-on into move i - 4 along the same line.
    if (i >= 4 && d[i - 1] === d[i - 3] && d[i] + d[i - 4] >= d[i - 2]) {
      return true;
    }
    // Move i hits move i - 5 after an outward spiral starts turning inward.
    if (i >= 5 && d[i - 2] >= d[i - 4] && d[i - 1] <= d[i - 3] && d[i - 1] + d[i - 5] >= d[i - 3] && d[i] + d[i - 4] >= d[i - 2]) {
      return true;
    }
  }
  return false;
}

