function isSelfCrossing(distance) {
  // Draw every move as an axis-aligned segment and test every pair that is not consecutive.
  const dx = [0, -1, 0, 1], dy = [1, 0, -1, 0];
  const segments = [];
  let x = 0, y = 0;
  for (let i = 0; i < distance.length; i++) {
    const nx = x + dx[i % 4] * distance[i], ny = y + dy[i % 4] * distance[i];
    segments.push([Math.min(x, nx), Math.max(x, nx), Math.min(y, ny), Math.max(y, ny)]);
    x = nx;
    y = ny;
  }
  for (let i = 0; i < segments.length; i++) {
    for (let j = 0; j + 1 < i; j++) {
      const [ax1, ax2, ay1, ay2] = segments[i], [bx1, bx2, by1, by2] = segments[j];
      // Two axis-aligned segments meet exactly when their x ranges and y ranges both overlap.
      if (Math.max(ax1, bx1) <= Math.min(ax2, bx2) && Math.max(ay1, by1) <= Math.min(ay2, by2)) return true;
    }
  }
  return false;
}

