function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const n = large ? 1500 + pick(501) : 1 + pick(10);
  const mode = pick(4);
  const distance = [];
  if (mode === 0) {
    // Short random moves: crossings and touches are common.
    const limit = large ? 100000 : 4;
    for (let i = 0; i < n; i++) distance.push(1 + pick(limit));
    return [distance];
  }
  const step = large ? 45 : 3;
  if (mode === 1 || mode === 3) {
    // Grow outward (each move longer than the one two back); mode 3 then continues at random.
    const turn = mode === 1 ? n : pick(n + 1);
    for (let i = 0; i < n; i++) {
      if (i < turn) distance.push(i < 2 ? 1 + pick(3) : distance[i - 2] + 1 + pick(step));
      else distance.push(1 + pick(i < 2 ? 3 : distance[i - 2] + 2));
    }
  } else {
    // Shrink inward (each move shorter than the one two back).
    const start = large ? 100000 : 30;
    for (let i = 0; i < n; i++) distance.push(i < 2 ? start - pick(3) : Math.max(1, distance[i - 2] - 1 - pick(step)));
  }
  // Sometimes nudge one late move so the path may touch an earlier one.
  if (n > 3 && rand() < 0.4) {
    const i = n - 1 - pick(Math.min(n - 3, 4));
    distance[i] = Math.max(1, Math.min(100000, distance[i - 2] + pick(3) - 1));
  }
  return [distance];
}
